'Amount_Paid' => 'Betaald bedrag',
'Payment_Amounts_Help' => 'Het betaalde bedrag vereffent het saldo en verlaagt het openstaande bedrag. Het ontvangen bedrag is het overhandigde contante geld: dit wordt alleen gebruikt om het terug te geven wisselgeld te berekenen en verandert het openstaande bedrag niet.',
