'Show_Previous_Dues_Line' => 'Regel eerdere openstaande bedragen tonen',
'Show_Previous_Dues_Line_Desc' => 'Saldo dat de klant vóór deze verkoop verschuldigd was. Alleen afgedrukt als het groter is dan nul.',
