'Show_Net_Balance_Line_Desc' => 'Eerdere openstaande bedragen plus wat nog openstaat op deze verkoop. Alleen afgedrukt als de eerdere openstaande bedragen groter zijn dan nul.',
'QZ_Tray_Printer' => 'QZ Tray (printer op deze computer)',
'QZ_Printer_Name_Hint' => 'De printernaam zoals die wordt weergegeven op de computer waarop QZ Tray draait. Laat leeg om de standaardprinter van die computer te gebruiken. Klik op ⟳ om printers te detecteren.',
'QZ_Not_Running' => 'QZ Tray draait niet op deze computer. Installeer het via qz.io en laat het draaien, en sta deze website toe wanneer QZ daarom vraagt.',
'Detect_Printers' => 'Printers detecteren',
'QZ_Download_Cert' => 'Certificaat downloaden (override.crt)',
'QZ_Setup_Title' => 'QZ Tray-afdrukken instellen (eenmalig, op elke computer die etiketten afdrukt)',
'QZ_Step_Install' => '1. Installeer QZ Tray op deze computer — download het gratis via qz.io, start het en laat het draaien (het staat in het systeemvak op Windows of in de menubalk op macOS).',
'QZ_Step_Connect' => '2. Sluit uw etiketprinter via USB aan en controleer of deze in het besturingssysteem is geïnstalleerd (Windows: Instellingen > Printers en scanners — macOS: Systeeminstellingen > Printers en scanners).',
'QZ_Step_Detect' => '3. Klik op de knop ⟳ naast "Printernaam" hierboven om de printers op deze computer te detecteren en selecteer daarna uw etiketprinter. Laat het veld leeg om de standaardprinter van de computer te gebruiken.',
'QZ_Step_Cert' => '4. Om af te drukken zonder toestemmingsvenster downloadt u het onderstaande certificaat en kopieert u het naar de installatiemap van QZ Tray, hernoemd naar override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Sluit QZ Tray daarna af en start het opnieuw.',
'QZ_Step_Test' => '5. Klik hieronder op "Testetiket afdrukken". Als QZ Tray om toestemming vraagt, klik dan op Toestaan — met het certificaat geïnstalleerd wordt dit niet opnieuw gevraagd.',
'QZ_Step_Save' => '6. Klik op Verzenden om deze instellingen op te slaan. Etiketten van de pagina Barcode afdrukken worden nu direct op deze printer afgedrukt, zonder afdrukvenster van de browser.',
'QZ_Setup_Note' => 'QZ Tray draait op de computer waarop u werkt, dus dit werkt ook als Stocky op een externe server wordt gehost. Elke computer die etiketten afdrukt, moet QZ Tray geïnstalleerd hebben.',
'PWA_Enabled' => 'Installeerbare app inschakelen',
'PWA_Enabled_Help' => 'Laat browsers aanbieden deze app te installeren op telefoons, tablets en desktops, en houdt offline pagina\'s in de cache. Als u dit uitschakelt, verdwijnt de installatieprompt overal en wordt de cache bij het volgende bezoek gewist.',
'PWA_Identity' => 'App-identiteit',
'PWA_Launch' => 'Opstarten en weergave',
'PWA_App_Name' => 'App-naam',
'PWA_App_Name_Help' => 'Getoond in de installatieprompt en in de lijst met apps. Laat leeg om de app-naam uit de weergave-instellingen te gebruiken.',
'PWA_Short_Name' => 'Korte naam',
'PWA_Short_Name_Help' => 'Getoond onder het pictogram op startschermen, waar lange namen worden afgekapt. Laat leeg om het deel van de app-naam vóór de "|" te gebruiken.',
'PWA_Description' => 'Beschrijving',
