'Label_Render_Mode' => 'Etiketweergave',
'Label_Render_Mode_Hint' => 'Hoe het etiket wordt getekend. Printerlettertypen is het snelst en geeft de scherpste barcode, maar drukt alleen eenvoudige Latijnse tekens af in het eigen lettertype van de printer. Voorbeeldafbeelding geeft uw etiketontwerp exact weer — uw gekozen lettertype, elke taal — zoals speciale etiketsoftware dat doet.',
'Render_Native' => 'Printerlettertypen (snelst)',
'Render_Raster' => 'Voorbeeldafbeelding (exact ontwerp)',
'Label_Width_Mm' => 'Etiketbreedte (mm)',
'Label_Height_Mm' => 'Etikethoogte (mm)',
'Label_Size_Hint' => 'De fysieke grootte van één sticker op de rol. Deze moet exact overeenkomen met de geladen etiketten — een verkeerde grootte laat de printer op de verkeerde plek naar de tussenruimte zoeken, waardoor elk etiket verder verschoven wordt afgedrukt.',
'Calibrate_Labels' => 'Etiketten kalibreren',
'Calibrate_Labels_Hint' => 'De printer voert een paar etiketten door om de sticker en de tussenruimte te meten. Voer dit eenmaal uit na het laden van een nieuwe rol, of wanneer de afdrukpositie verschuift.',
'Calibration_Sent' => 'Kalibratie gestart — de printer voert een paar lege etiketten door om ze te meten. Voer een testafdruk uit wanneer de printer stopt.',
'Label_Printer_Dpi' => 'Resolutie printkop',
'Label_Printer_Dpi_Hint' => 'De meeste etiketprinters zijn 203 dpi. Niet zeker? Gebruik de knop "Resolutie bepalen" hieronder — die drukt het antwoord af.',
'Find_Resolution' => 'Resolutie bepalen',
'Find_Resolution_Hint' => 'Drukt twee etiketten af, gemarkeerd met 203 en 300. Het juiste toont een volledige rechthoek op de sticker met een kleine, gelijke marge aan alle vier zijden; bij het verkeerde ontbreken randen of loopt de afdruk door op de volgende sticker.',
'Dpi_Test_Sent' => 'Er worden twee etiketten afgedrukt, gemarkeerd met 203 en 300. Het juiste toont een volledige rechthoek met een kleine, gelijke marge aan alle vier zijden — stel "Resolutie printkop" in op dat getal en sla op.',
'Label_Offset_X' => 'Horizontale verschuiving (mm)',
'Label_Offset_X_Hint' => 'Verschuift de afdruk zijwaarts op de sticker. Gebruik dit wanneer tekst aan één zijkant wordt afgesneden — bijv. 2.5 wanneer de witte sticker gecentreerd op een breder dragerpapier zit. Pas aan in stappen van 0.5.',
'Label_Offset_Y' => 'Verticale verschuiving (mm)',
