'Enable_Wholesale_Pricing_Hint' => 'Laat producten staffelprijzen hebben (10-19 st., 20-49 st., 100+ ...) die automatisch de verkoopprijs in de POS en de online winkel vervangen zodra het bestelde aantal een staffel bereikt. Schakel het uit en alles wordt weer tegen de normale verkoopprijs verkocht — ingestelde staffels blijven bewaard, maar worden niet toegepast.',
