'Ord_Guide_Lifecycle_Title' => 'Bestelstatus',
'Ord_Guide_Lifecycle_Pending' => 'Een nieuwe bestelling die wacht op uw beoordeling. Alleen een bestelling in behandeling kan worden bevestigd of geannuleerd.',
'Ord_Guide_Lifecycle_Confirmed' => 'U heeft de bestelling geaccepteerd. Stocky maakt een verkoop aan in het magazijn dat u koos en boekt de voorraad af — die verkoop is het record waaruit uw voorraad-, betalings- en winstrapporten lezen.',
