'Ord_Guide_PaymentStatus_Tip' => 'Ingesteld bij het afrekenen en hier niet te bewerken. Klik om te zien hoe u de betaling registreert.',
'Ord_Guide_Payment_Title' => 'Betalingsstatus',
'Ord_Guide_Payment_Intro' => 'Deze kolom registreert hoe de klant bij het afrekenen heeft gekozen te betalen. Deze wordt ingesteld door de webwinkel en kan op deze pagina niet worden bewerkt — het geld zelf wordt bijgehouden op de verkoop die bij het bevestigen van de bestelling wordt aangemaakt.',
'Ord_Guide_Payment_Paid' => 'De klant heeft al online betaald via een betaalprovider. Bij het bevestigen van de bestelling wordt de verkoop als Betaald aangemaakt en wordt de betaling voor u geregistreerd — u hoeft verder niets te doen.',
'Ord_Guide_Payment_Pending' => 'Rembours, bankoverschrijving of een andere methode voor later betalen. Bij het bevestigen van de bestelling wordt de verkoop als Onbetaald aangemaakt, dus u registreert het geld zelf zodra u het int — zie de onderstaande stappen.',
'Ord_Guide_Payment_Failed' => 'De betaalprovider heeft de betaling geweigerd of de klant heeft deze afgebroken. De bestelling wordt automatisch geannuleerd.',
'Ord_Guide_MarkPaid_Title' => 'Een betaling wijzigen van in behandeling naar betaald',
'Ord_Guide_MarkPaid_Step1' => 'Bevestig hier eerst de bestelling — door te bevestigen wordt de verkoop aangemaakt.',
'Ord_Guide_MarkPaid_Step2' => 'Open Verkopen > Alle verkopen en zoek die verkoop (dezelfde klant; de detailpagina toont de online bestelling waaruit deze afkomstig is).',
'Ord_Guide_MarkPaid_Step3' => 'Open het actiemenu van de rij en kies Betaling aanmaken.',
