'Upd_Manual_Steps_Intro' => 'Volg deze stappen om uw applicatie bij te werken',
'Upd_Note_Permission_Only' => 'Opmerking 2: alleen een beheerder of een gebruiker met de machtiging "{perm}" kan het systeem upgraden',
'Upd_Manual_Step_Backup_Db' => 'Maak een back-up van uw database. Ga naar {backup}, klik op Back-up genereren — u vindt deze in {path} — of exporteer uw database vanuit PhpMyAdmin en sla deze op uw pc op.',
'Upd_Manual_Step_Backup_Files' => 'Maak een back-up van uw bestanden voordat u bijwerkt.',
'Upd_Manual_Step_Download' => 'Download de nieuwste versie vanuit uw CodeCanyon-account en pak deze uit.',
'Upd_Manual_Step_Remove' => 'Verwijder de vorige bestanden, {except}:',
'Upd_Except' => 'behalve',
'Upd_File_Label' => 'bestand: {name}',
'Upd_Folder_Label' => 'map: {name}',
'Upd_Manual_Step_Reupload' => 'Upload de bestanden en mappen van de nieuwe update opnieuw, {except} dezelfde drie paden hierboven.',
'Upd_Manual_Step_Visit' => 'Ga naar {url} om uw database bij te werken.',
'Upd_Manual_Step_Clear_Cache' => 'Wis de cache van uw browser volledig.',
'Upd_Manual_Step_Done' => 'U bent klaar! Veel plezier met de bijgewerkte applicatie.',
'Upd_Note_Blank_Pages' => 'Opmerking: Als pagina\'s niet laden of leeg zijn, zorg er dan voor dat u de browsercache heeft gewist.',
'Upd_Guide_Before_Title' => '1. Voordat u bijwerkt',
'Upd_Guide_Before_Download' => 'Download het {package} van de applicatie vanuit uw CodeCanyon-account ({path}). Pak het niet uit — de updater heeft de ZIP precies zoals gedownload nodig.',
'Upd_Latest_Full_Zip' => 'nieuwste volledige ZIP-pakket',
'Upd_Guide_Before_Admin' => 'Zorg dat u bent ingelogd als beheerder met de machtiging {perm}. Niemand anders kan de updater zien of uitvoeren.',
'Upd_Guide_Before_Quiet' => 'Kies een rustig moment: tijdens de update schakelt de applicatie kort over naar onderhoudsmodus en worden andere gebruikers buitengesloten.',
'Upd_Guide_Before_No_Manual' => 'U hoeft {not} handmatig een back-up te maken, bestanden uit te pakken, opdrachten uit te voeren, configuratiebestanden te bewerken of de database aan te raken — de updater doet dat allemaal automatisch. (Een extra handmatige back-up kan natuurlijk nooit kwaad.)',
'Upd_Not' => 'niet',
'Upd_Guide_Code_Overwritten' => 'Als u de applicatiecode handmatig heeft gewijzigd, worden uw wijzigingen door de update overschreven. Uw gegevens, uploads, instellingen en .env blijven altijd behouden.',
'Upd_Guide_Running_Title' => '2. De update uitvoeren',
'Upd_Guide_Run_Open' => 'Open {path} (deze pagina) en blijf op het tabblad {tab}.',
'Upd_Guide_Run_Upload' => '{upload}: klik op het uploadvak of sleep het gedownloade pakket erin. Grote bestanden worden in kleine stukken geüpload, dus dit werkt ook op shared hosting met lage uploadlimieten. Een checksum beschermt tegen beschadigde of onvolledige uploads.',
'Upd_Upload_The_Zip' => 'Upload de ZIP',
'Upd_Guide_Run_Validation' => '{auto} na het uploaden (u kunt deze opnieuw uitvoeren met de knop {button}). Het systeem controleert: ZIP-integriteit, pakketstructuur en volledigheid, versiecompatibiliteit (downgrades worden geweigerd), vereiste PHP-versie en extensies, bestandsrechten, vrije schijfruimte, databaseverbinding, configuratie, en dat er geen andere update actief is.',
'Upd_Validation_Runs_Automatically' => 'Validatie wordt automatisch uitgevoerd',
'Upd_Guide_Run_Review' => 'Bekijk het paneel {panel}. De knop {button} verschijnt alleen als elke kritieke controle slaagt. Als een controle mislukt, vertelt de melding precies wat u moet oplossen.',
'Upd_Guide_Run_Click' => 'Klik op {button} en bevestig. Daarna gewoon: {keep} en volg de voortgangsbalk. Het systeem voert in volgorde uit:',
'Upd_Keep_Page_Open' => 'deze pagina open houden',
'Upd_Guide_Phase_Backup' => '{label} — een volledige databasedump, een ZIP van elk applicatiebestand dat de update kan wijzigen, en een kopie van {env} worden aangemaakt en {verified}. Uw uploads ({images}) en {storage} worden nooit door een update aangeraakt, dus ze worden niet gearchiveerd. Als er geen back-up kan worden gemaakt, stopt de update hier en wordt er niets gewijzigd.',
'Upd_Verified' => 'geverifieerd',
'Upd_Guide_Phase_Prepare' => '{label} — de nieuwe versie wordt uitgepakt in een staging-omgeving en opnieuw gevalideerd. De live applicatie blijft onaangeroerd.',
'Upd_Guide_Phase_Maintenance' => '{label} — onderhoudsmodus wordt ingeschakeld; bezoekers zien een vriendelijk scherm "We zijn zo terug".',
'Upd_Guide_Phase_Files' => '{label} — de nieuwe bestanden worden vrijwel direct omgewisseld; de oude bestanden worden apart bewaard voor terugdraaien. Beschermde paden ({env}, {storage}, {images}) worden nooit vervangen.',
'Upd_Guide_Phase_Database' => '{label} — migraties worden uitgevoerd, daarna worden machtigingen, vertalingen en sjablonen vernieuwd.',
'Upd_Guide_Phase_Cache' => '{label} — alle caches worden gewist en opnieuw opgebouwd.',
'Upd_Guide_Phase_Verify' => '{label} — gezondheidscontroles bevestigen dat de nieuwe versie opstart, de database werkt, alle migraties zijn uitgevoerd en de configuratie geldig is.',
'Upd_Guide_Phase_Done' => '{label} — onderhoudsmodus wordt opgeheven en tijdelijke bestanden worden opgeruimd.',
'Upd_Guide_Run_Success' => 'Wanneer u {success} ziet, klik op {reload} en vernieuw uw browser volledig ({keys}) zodat de nieuwe beheerpaneelbestanden worden geladen.',
'Upd_Update_Successful_Short' => 'Update geslaagd',
'Upd_Guide_No_Internet' => 'Tijdens de update is geen internetverbinding nodig — alles komt uit de geüploade ZIP. Het verliezen van de verbinding of het sluiten van de browser breekt de update NIET af: de server onthoudt precies waar deze is gestopt.',
'Upd_Guide_Wrong_Title' => '3. Als er iets misgaat',
'Upd_Guide_Wrong_Rollback' => '{label} — als er iets mislukt nadat bestanden zijn gaan veranderen (uitpakfout, mislukte migratie, mislukte gezondheidscontrole, volle schijf, …), herstelt het systeem automatisch de vorige bestanden en de database vanuit de geverifieerde back-up, heft het de onderhoudsmodus op en meldt het {message}. U staat dan precies waar u begon.',
'Upd_Automatic_Rollback' => 'Automatisch terugdraaien',
'Upd_Failed_Previous_Restored' => 'Update mislukt — vorige versie hersteld',
'Upd_Guide_Wrong_Interrupted' => '{label} (serverherstart, time-out, gesloten browser, stroomuitval) — wanneer u deze pagina opnieuw opent, biedt een rode banner twee veilige keuzes: {resume} (hervat vanaf precies de stap waar deze stopte) of {rollback} (herstelt de vorige versie vanuit de back-up).',
'Upd_Interrupted_Update' => 'Onderbroken update',
'Upd_Guide_Wrong_Unreachable' => '{label} — gebruik de zelfstandige {console} op {path}. Deze werkt zelfs als de site in onderhoudsmodus staat of de beheerpaneelbestanden defect zijn, en biedt dezelfde acties Doorgaan / Terugdraaien. Er is ook een onopvallende link "Beheerderstoegang" onderaan het onderhoudsscherm.',
'Upd_Admin_Unreachable' => 'Beheerpaneel onbereikbaar',
'Upd_Recovery_Console' => 'herstelconsole',
'Upd_Guide_Wrong_Locked_Out' => '{label} — terwijl een update loopt, toont deze pagina een {link}. Bewaar deze als u weer binnen moet komen (bijvoorbeeld nadat uw sessie is verlopen); hiermee komt u langs het onderhoudsscherm zodat u opnieuw kunt inloggen.',
'Upd_Locked_Out_Maintenance' => 'Buitengesloten door onderhoudsmodus',
'Upd_Bypass_Link' => 'omzeilingslink',
'Upd_Guide_Wrong_Concurrent' => '{label} — die ziet {message} Er kan altijd maar één update tegelijk worden uitgevoerd.',
'Upd_Another_Admin_Updating' => 'Een andere beheerder probeert tegelijkertijd bij te werken',
'Upd_Guide_Backups_Title' => '4. Back-ups & herstel',
'Upd_Guide_Backups_Created' => 'Elke update maakt een back-up {before} er iets wordt aangeraakt: alle applicatiebestanden die de update kan vervangen, een kopie van {env} en een volledige databasedump. Uploads en {storage} worden nooit door een update gewijzigd en maken er daarom geen deel van uit — maak daar zelf back-ups van. Back-ups staan in {path} en zijn nooit toegankelijk via het web.',
'Upd_Before' => 'voordat',
'Upd_Guide_Backups_Panel' => 'Het paneel {panel} op het tabblad {tab} toont ze met datum, versie en grootte. Daar kunt u elke volledige back-up {restore} (bestanden + database — er wordt eerst een veiligheidskopie van de huidige database gemaakt) of oude back-ups {delete}.',
'Upd_Restore_Verb' => 'herstellen',
'Upd_Delete_Verb' => 'verwijderen',
'Upd_Guide_Backups_Retention' => 'Gebruik {keep} om te kiezen hoeveel back-ups worden bewaard; oudere worden na elke geslaagde update automatisch verwijderd. De enige resterende volledige back-up kan nooit worden verwijderd — u houdt altijd een weg terug.',
'Upd_Guide_Manual_Title' => '5. Handmatige update (alternatieve methode)',
'Upd_Guide_Manual_Text' => 'Als u liever handmatig bijwerkt, of de uploader niet op uw server kan worden gebruikt, volg dan de stapsgewijze instructies op het tabblad {tab} van deze pagina.',
'Upd_Guide_Clear_Cache_First' => 'Als pagina\'s er na een update defect of leeg uitzien, wis dan eerst uw browsercache — dat is bijna altijd de oorzaak.',
'Upd_Restore_Backup_Confirm' => 'Deze back-up herstellen? De huidige bestanden en de huidige database worden vervangen door de back-up. Er wordt eerst een veiligheidskopie van de huidige database gemaakt. (v{version} — {date})',
'Woo_Guide_Lead' => 'Hoe een WooCommerce-winkel gelijk blijft met het ERP. De onderstaande cronregels zijn voor deze server opgesteld, zodat ze er direct op kunnen worden gekopieerd.',
'Woo_Guide_Ways_Note' => 'In tegenstelling tot Shopify stuurt WooCommerce zelf niets naar het ERP — er is hier geen webhook-ontvanger, dus alles wat {in} komt, arriveert volgens schema. Alleen voorraad die {out} gaat, kan direct zijn.',
'Woo_In' => 'binnen',
'Woo_Out' => 'naar buiten',
'Woo_Guide_Both_Ways_Title' => 'Beide richtingen hebben dit eerst nodig',
'Woo_Api_Keys' => 'API-sleutels',
'Woo_Guide_Api_Keys_Text' => '{path}, machtiging {perm}. Kopieer de consumer key en secret naar het tabblad {settings}, samen met de winkel-URL — het adres van uw site zonder afsluitende slash, bijv. {example}.',
'Woo_Credentials_Saved' => 'inloggegevens opgeslagen',
'Woo_Not_Configured_Yet' => 'nog niet geconfigureerd',
'Woo_Guide_Wp_App_Password_Title' => 'WordPress-applicatiewachtwoord (optioneel)',
'Woo_Guide_Wp_App_Password_Text' => 'Alleen gebruikt voor productafbeeldingen. De WooCommerce-API verplaatst producten, voorraad, categorieën, merken, klanten en bestellingen; de WordPress-API doorzoekt de Mediabibliotheek en uploadt een afbeelding die er nog niet is.',
'Woo_Guide_Wp_App_Password_Note' => 'Gebruik een WordPress-gebruiker die media mag beheren en maak het wachtwoord aan onder {path}. Laat beide velden leeg en alles wordt nog steeds gesynchroniseerd — alleen het koppelen van afbeeldingen wordt overgeslagen.',
'Woo_Guide_Pick_Way_Title' => 'Kies daarna hoe het gelijk blijft',
'Woo_Right_Away' => 'Direct',
'Woo_Stock_Live' => 'voorraad live',
'Woo_Stock_Not_Live' => 'voorraad niet live',
'Woo_Guide_Realtime_Lead' => 'Slechts één richting: voorraad en producten die het ERP verlaten. Bestellingen en productwijzigingen in WooCommerce komen nog steeds volgens schema binnen — zie het andere tabblad.',
'Woo_Push_Stock_On_Change' => 'Voorraad pushen zodra deze verandert',
'Woo_Setting_People_Miss' => 'Dit is de instelling die mensen over het hoofd zien',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Een POS-verkoop {not} vanzelf bij WooCommerce. Staat dit uit, dan merkt de winkel het pas bij de volgende voorraadsynchronisatie — standaard een uur — en in die tijd kan deze een eenheid verkopen die u al aan de kassa heeft verkocht.',
'Woo_Does_Not' => 'komt niet',
'Woo_Guide_Tick_Instant' => 'Vink {option} aan op het tabblad {settings}. Dat is de hele installatie — geen worker, geen cron. Elke verkoop, retour, correctie, overboeking en ontvangen inkoop stuurt dan een push van alleen die producten, direct nadat de verkoop is opgeslagen, en een verkoop met twintig regels kost één push, geen twintig. De kassa wacht er nooit op.',
'Woo_Currently' => 'Momenteel:',
'Woo_Instant_On_Text' => 'aan — voorraad gepusht bij wijziging',
'Woo_Instant_Off_Text' => 'uit — voorraad alleen volgens schema',
'Woo_Guide_Instant_Note' => 'Alleen producten die al aan WooCommerce zijn gekoppeld, worden gepusht — een product dat nooit is gesynchroniseerd, heeft niets in de winkel om te corrigeren. Variabele producten gaan via hun hoofdproduct, en een combo wordt opnieuw gepusht wanneer een van de componenten verandert. Bulkbewerkingen (een product verwijderen, een magazijn resetten) schrijven voorraad zonder een gebeurtenis te activeren, wat een reden is om ook de uurlijkse voorraadsynchronisatie te behouden.',
'Woo_Push_Products_On_Save' => 'Producten pushen zodra ze worden opgeslagen',
'Woo_Guide_Tick_Auto_Products' => 'Vink {option} aan op het tabblad {settings} en een product dat in Stocky wordt aangemaakt, bewerkt of gedupliceerd, wordt direct na opslaan naar WooCommerce gestuurd — gegevens, prijs, varianten en afbeeldingen, daarna de voorraad. Een nieuw product wordt meteen in de winkel aangemaakt in plaats van te wachten op de nachtelijke productsynchronisatie.',
'Woo_On' => 'aan',
'Woo_Off' => 'uit',
'Woo_Guide_Bulk_Imports_Note' => 'Bulkimports worden niet één voor één gepusht — voer na een import een productsynchronisatie uit. Synchroniseer eerst categorieën en merken, zodat een gepusht product in de juiste categorie terechtkomt.',
'Woo_Nothing_Else_To_Install' => 'Verder niets te installeren',
'Woo_Guide_Same_Process' => 'Geen wachtrij-worker, geen cronregel. De push draait in hetzelfde proces dat de verkoop afhandelde, {after} het antwoord is teruggestuurd, dus de kassa wacht nooit op WooCommerce. Pushes overlappen nooit: wijzigingen tijdens een lopende push wachten daarop en gaan er direct daarna uit.',
'Woo_After' => 'nadat',
'Woo_Guide_Shop_Stops_Answering' => 'Een winkel die niet meer reageert, wordt na acht seconden opgegeven en pushes pauzeren vijf minuten zodat niet elke verkoop er opnieuw op wacht; de wijzigingen die ondertussen binnenkwamen gaan mee met de eerste push na de pauze, en de uurlijkse voorraadsynchronisatie haalt sowieso alles in. Elke pauze wordt vastgelegd op het tabblad Logboeken.',
'Woo_Guide_Artisan_Exception' => 'Eén uitzondering: een voorraadwijziging door een artisan-opdracht heeft geen antwoord om op te wachten, dus die wordt in plaats daarvan in de wachtrij {queue} geplaatst. Om ook die snel te laten verzenden, verwerkt u die wachtrij:',
'Woo_Cron_Line_Copied' => 'Cronregel gekopieerd',
'Woo_Command_Copied' => 'Opdracht gekopieerd',
'Woo_Guide_Not_Woo_Queue' => 'Bewust niet de wachtrij {queue}: die draagt de urenlange catalogusbatches, en een directe push achter een daarvan zou niet direct zijn.',
'Woo_On_A_Schedule' => 'Volgens schema',
'Woo_Guide_Scheduled_Lead' => 'Alles wordt regelmatig opnieuw gecontroleerd, in beide richtingen. Zo komen bestellingen in het ERP, zo wordt een catalogus gepubliceerd, en zo wordt hersteld wat de snelle route heeft gemist. Elke taak krijgt een eigen cronregel, dus u voert alleen uit wat u wilt.',
'Woo_Guide_Sync_Drains_Queue' => '{command} verwerkt zijn eigen wachtrij terwijl het draait, dus deze regels hebben geen aparte worker nodig. Gebruik op Windows Taakplanner met programma {program} en dezelfde argumenten, gestart in {path}.',
'Woo_Or_No_Cron' => 'Of helemaal geen cron',
'Woo_Guide_No_Cron_Text' => 'Elk tabblad hier synchroniseert op verzoek, en een handmatige synchronisatie verwerkt zijn eigen batches zolang de pagina open is — dus een kleine winkel kan zonder cronregel werken. Wat u mist, is alles wat gebeurt terwijl niemand kijkt: bestellingen komen alleen binnen als iemand op de knop drukt.',
'Woo_Commands_Worth_Knowing' => 'Handige opdrachten',
'Woo_Worth_Knowing' => 'Goed om te weten',
'Woo_Guide_Changing_Url_Clears' => 'Het wijzigen van de winkel-URL of de API-sleutels wist elke koppeling — producten, categorieën, merken en klanten worden allemaal opnieuw met de nieuwe winkel gesynchroniseerd.',
'Woo_Guide_Keep_Skus' => 'Houd SKU\'s consistent tussen Stocky en WooCommerce: dat voorkomt duplicaten en maakt opnieuw koppelen veilig.',
'Woo_Guide_Stock_Total' => 'Voorraad die naar Woo wordt gepubliceerd, is het {total}, niet het cijfer van één magazijn.',
'Woo_Total_Across_Warehouses' => 'totaal over alle magazijnen',
'Woo_Guide_Full_Reference' => 'De volledige referentie — elk bereik, hoe de wachtrij werkt en een probleemoplossingslijst — staat in {file}.',
'Woo_Way_Covers' => 'Omvat',
'Woo_Way_Covers_Realtime' => 'Alleen voorraad die het ERP verlaat — een POS-verkoop, een retour, een correctie, een ontvangen inkoop',
'Woo_Way_Covers_Scheduled' => 'Alles, in beide richtingen: bestellingen en productwijzigingen binnen, catalogus en voorraad naar buiten',
'Woo_Way_Speed' => 'Snelheid',
'Woo_Way_Seconds' => 'Seconden',
'Woo_Way_Speed_Scheduled' => 'Wat u in de cronregel zet (voorraad elk uur, bestellingen elke 15 min)',
'Woo_Way_Needs' => 'Vereist',
'Woo_Way_Needs_Realtime' => 'Niets — alleen de instelling',
'Woo_Way_Needs_Scheduled' => 'Een cronregel per taak — of niets, als u handmatig synchroniseert',
'Woo_Way_Switched_On_At' => 'Ingeschakeld bij',
'Woo_Way_Cron_Entries_Below' => 'De onderstaande cronregels',
'Woo_Cron_Orders' => 'Bestellingen elke 15 minuten — alleen de gewijzigde sinds de vorige run.',
'Woo_Cron_Products_Pull' => 'Productwijzigingen uit de winkel, elke nacht om 03:00.',
'Woo_Cron_Customers' => 'Klanten, elke nacht om 03:30.',
'Woo_Cron_Stock' => 'Voorraad elk uur — het vangnet onder de directe push, en de enige voorraadsynchronisatie zonder.',
'Woo_Cron_Products_Push' => 'Nog niet gekoppelde producten, elke nacht om 02:00. Bestaande producten worden niet herschreven.',
'Woo_Cmd_Stock' => 'Push nu de voorraad voor elk gekoppeld product.',
'Woo_Cmd_Products_Unsynced' => 'Publiceer producten die nog geen WooCommerce-id hebben.',
'Woo_Cmd_Orders' => 'Importeer bestellingen die sinds de vorige run zijn gewijzigd.',
'Woo_Cmd_Orders_Full' => 'Scan elke bestelling opnieuw in plaats van alleen recente wijzigingen.',
'Woo_Cmd_Pull' => 'Alles inkomend tegelijk: producten, bestellingen, klanten.',
'Woo_Guide_Page_Title' => 'WooCommerce-handleiding',
'Woo_Guide_Page_Subtitle' => 'De winkel koppelen, wat vanzelf draait, en de cronregels voor deze server',
'Woo_Settings_Button' => 'WooCommerce-instellingen',
'Woo_No_Shop_Connected' => 'Er is nog geen winkel gekoppeld',
'Woo_No_Shop_Connected_Desc' => 'Alles hieronder blijft van toepassing — voer de winkel-URL en API-sleutels in op de WooCommerce-instellingenpagina en kom dan terug.',
'Woo_Wp_Username' => 'WordPress-gebruikersnaam',
'Woo_Wp_App_Password' => 'WordPress-applicatiewachtwoord',
'Woo_Settings_Instant_Hint' => 'Een verkoop, retour of correctie stuurt direct bij het opslaan een voorraadpush voor alleen die producten, zodat de winkel binnen enkele seconden klopt in plaats van bij de volgende uurlijkse voorraadsynchronisatie. Verder niets te installeren — de push draait nadat de verkoop is afgehandeld, dus de kassa wacht nooit op WooCommerce. Meer op het tabblad {guide}.',
'Woo_Settings_Instant_Off_Alert' => 'Laat dit uit en een POS-verkoop komt pas bij de volgende voorraadsynchronisatie bij WooCommerce — tot een uur later.',
'Woo_Settings_Auto_Products_Hint' => 'Een product dat in Stocky wordt aangemaakt, bewerkt of gedupliceerd, wordt direct na opslaan naar WooCommerce gestuurd — gegevens, prijs, varianten, afbeeldingen, daarna de voorraad — in plaats van te wachten op een productsynchronisatie. Bulkimports worden niet gepusht; voer na een import een productsynchronisatie uit.',
'Woo_Sync_Tuning' => 'Synchronisatie afstemmen',
'Woo_Sync_Tuning_Intro' => 'De standaardwaarden passen bij de meeste winkels. Wijzig deze alleen als synchronisatie traag is of een time-out geeft op uw hosting. Elke waarde is begrensd tot een veilig bereik, en een veld leegmaken herstelt de standaardwaarde.',
'Woo_Setting_This_Up' => 'Dit instellen',
'Woo_Setting_This_Up_Text' => 'De API-sleutels ophalen, waar het WordPress-applicatiewachtwoord voor dient, de cronregels voor geplande synchronisaties, en hoe voorraad de winkel bereikt zodra deze verandert — het staat allemaal op het tabblad Handleiding, met de cronregels van deze server klaar om te kopiëren. Eén exemplaar, zodat het niet kan afwijken van wat de module daadwerkelijk doet.',
'Woo_Open_The_Guide' => 'De handleiding openen',
'Woo_Sync_Stock' => 'Voorraad synchroniseren',
'Woo_Orders_Stat' => 'WooCommerce-bestellingen',
'Woo_Imported' => 'Geïmporteerd',
'Woo_Imported_Today' => 'Vandaag geïmporteerd',
'Woo_Unknown_Error' => 'Onbekende fout',
'Woo_Orders_Sync_Failed' => 'Synchronisatie van bestellingen mislukt: {error}',
'Woo_Order_Synced' => 'Bestelling gesynchroniseerd',
'Woo_Order_Sync_Failed' => 'Synchronisatie van bestelling mislukt: {error}',
'Woo_Orders_Sync_Completed' => 'Synchronisatie van bestellingen voltooid',
'Woo_Recent_Activity' => 'Recente activiteit',
'Woo_Fix_Product_Categories' => 'Productcategorieën herstellen',
'Woo_Auto_Link_By_Sku' => 'Automatisch koppelen op SKU',
'Woo_Unmapped_Report' => 'Rapport niet-gekoppeld',
'Woo_Order_Import_Failures' => 'Mislukte bestellingsimports',
'Woo_Unlinked_Products' => 'Niet-gekoppelde producten',
'Woo_Unlinked_Variants' => 'Niet-gekoppelde varianten',
'Woo_Product_ID' => 'Woo-product-ID',
'Woo_Variation_ID' => 'Woo-variatie-ID',
'Woo_Failures' => 'Mislukkingen',
'Woo_Last_Order' => 'Laatste bestelling',
'Woo_Last_Seen' => 'Laatst gezien',
'Woo_Sku_Code' => 'SKU / Code',
'Woo_Fix_Categories_Result' => 'Hersteld: {fixed} · Overgeslagen: {skipped} · Fouten: {errors}',
