'Telegram_G_A_Body' => 'Een verkoop, inkoop, betaling of uitgave die in Stocky wordt opgeslagen — in de POS of in het beheer — wordt naar Telegram gestuurd {after} deze is opgeslagen, in hetzelfde verzoek. Geen cronregel, geen wachtrij-worker, en de kassier wacht nooit op Telegram: de verkoop is al afgehandeld wanneer het bericht vertrekt.',
