'Shopify_Could_Not_Load_Store' => 'Kan deze winkel niet laden',
'Shopify_G_Lead_Store' => 'Wat deze winkel nodig heeft om gelijk te blijven. Alles hier is specifiek voor deze winkel — de paden en ID\'s zijn echt, dus de opdrachten kunnen direct op de server worden gekopieerd.',
'Shopify_G_Lead_Generic' => 'Hoe een Shopify-winkel gelijk blijft met het ERP. Kies hierboven een winkel om de eigen status te zien, of lees het zoals het is — de cronregel en de webhook-URL zijn hetzelfde, welke winkel u ook verbindt.',
'Shopify_G_Ways_Note' => 'De meeste winkels gebruiken beide: de eerste houdt de winkel van minuut tot minuut actueel, de tweede vangt op wat de eerste miste — een webhook die nooit aankwam, een wijziging direct in het Shopify-beheer, een nacht waarin de site plat lag.',
'Shopify_G_Both_Need' => 'Beide richtingen hebben dit eerst nodig',
'Shopify_G_Credentials' => 'Shopify-inloggegevens',
'Shopify_G_Cred_Intro' => 'Sinds januari 2026 maakt Shopify geen aangepaste apps meer aan binnen het beheer, dus er zijn twee soorten verbindingen:',
'Shopify_G_Cred_DevDash' => '{app} (elke winkel die nu wordt verbonden) — {path}. Ken de Admin API-scopes toe voor wat deze winkel synchroniseert, installeer de app in de winkel en kopieer daarna de {clientId} en {clientSecret} van de Settings-pagina van de app naar {where}. Het ERP wisselt deze zelf in voor een toegangstoken en vernieuwt dit voordat het elke 24 uur verloopt. Het client secret ondertekent ook webhooks, dus verder is er niets nodig. De app en de winkel moeten in dezelfde Shopify-organisatie zitten.',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard-app',
'Shopify_G_Cred_Legacy' => '{app} (vóór 2026 in het beheer aangemaakt) — blijft ongewijzigd werken met het {token} ({prefix}) en de {secret} als webhook-ondertekeningssecret. Niet dezelfde waarde als het token, en ze verwisselen is de gebruikelijke reden dat webhooks worden geweigerd.',
'Shopify_G_Legacy_App' => 'Verouderde aangepaste app',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'opgeslagen',
'Shopify_G_Missing_Refused' => 'ontbreekt — leveringen worden geweigerd',
'Shopify_G_Where_Data_Desc' => '{path} Het ERP-magazijn waarvan deze winkel de voorraad verkoopt, en de Shopify-locatie waarnaar die voorraad wordt geschreven. Voorraadsynchronisatie en bestellingsimport weigeren allebei te draaien zonder deze.',
'Shopify_G_Currently' => 'Momenteel: magazijn {warehouse}, locatie {location}',
'Shopify_G_Not_Set_Lower' => 'niet ingesteld',
'Shopify_G_Ready' => 'gereed',
'Shopify_G_Incomplete' => 'onvolledig',
'Shopify_G_Manual_Syncs' => 'Synchronisaties die u handmatig start',
'Shopify_G_Manual_Desc' => 'Een synchronisatie gestart vanuit het {centre} antwoordt direct en draait op de achtergrond, in korte delen die elk verdergaan waar de vorige stopte. Een grote catalogus wordt nooit halverwege afgebroken door hosting die lange webverzoeken beëindigt (LiteSpeed, nginx, een load balancer), en de pagina sluiten stopt het niet. De worker daarvoor is nog één cronregel:',
'Shopify_G_Cron_Copied' => 'Cronregel gekopieerd',
'Shopify_G_Manual_Note' => 'Zonder die regel wordt een synchronisatie nog steeds voltooid, maar alleen zolang de pagina Sync Centre open blijft: wanneer geen worker een run binnen enkele seconden oppakt, zet de pagina deze zelf voort, één kort verzoek per keer. Gebruik op Windows elke minuut Taakplanner: programma {program}, argumenten {args}, gestart in {dir}.',
'Shopify_G_Then_Pick' => 'Kies daarna hoe het gelijk blijft',
'Shopify_G_Right_Away' => 'Direct',
'Shopify_G_Stock_Live' => 'voorraad live',
'Shopify_G_Stock_Not_Live' => 'voorraad niet live',
'Shopify_G_Realtime_Lead' => 'Elke wijziging wordt verzonden zodra deze plaatsvindt, binnen seconden. Twee helften, en het zijn aparte schakelaars: {webhooks} brengen de eigen gebeurtenissen van de winkel binnen, en {push} stuurt voorraad naar buiten.',
'Shopify_G_Webhooks_Lower' => 'webhooks',
'Shopify_G_Instant_Push_Lower' => 'directe voorraadpush',
'Shopify_G_Webhooks_In' => 'Webhooks — de winkel → het ERP',
'Shopify_G_Webhooks_Desc' => 'Bestellingen, wijzigingen in bestellingsstatus, en product-, klant- en voorraadwijzigingen in Shopify. Open de winkel en druk op {button} op het {tab} — veilig om twee keer te drukken. Shopify post naar:',
'Shopify_G_Webhooks_Tab' => 'tabblad Webhooks',
'Shopify_G_Webhooks_Note' => 'Het adres moet via internet bereikbaar zijn over HTTPS — Shopify levert niet aan {localhost} of een {test}-domein. Elke levering wordt één keer vastgelegd, dus de herhaalpogingen van Shopify kunnen geen dubbele bestelling aanmaken, en een mislukte levering kan opnieuw worden afgespeeld. Leveringen worden geweigerd totdat het ondertekeningssecret uit stap 1 is opgeslagen.',
'Shopify_G_Instant_Out' => 'Directe voorraadpush — het ERP → de winkel',
'Shopify_G_Setting_Missed' => 'Dit is de instelling die mensen over het hoofd zien',
'Shopify_G_Pos_Not_Auto' => 'Een POS-verkoop komt {not} vanzelf bij Shopify. Staat dit uit, dan merkt de winkel het pas bij de volgende stap voorraadpush — en in die tijd kan deze een eenheid verkopen die u al aan de kassa heeft verkocht.',
'Shopify_G_Not' => 'niet',
'Shopify_G_Tick_Push' => 'Vink {setting} aan op {where}. Dat is de hele installatie — geen worker, geen cron. Elke verkoop, retour en correctie stuurt dan een push van alleen die producten, direct nadat de verkoop is opgeslagen, en een verkoop met twintig regels kost één push, geen twintig. De kassa wacht er nooit op.',
'Shopify_G_This_Store' => 'Deze winkel:',
'Shopify_G_Push_On' => 'aan — voorraad gepusht bij wijziging',
'Shopify_G_Push_Off' => 'uit — voorraad alleen volgens schema',
'Shopify_G_Push_Note' => 'Alleen producten die al een Shopify-koppeling hebben, en alleen bewegingen in het magazijn van deze winkel, worden gepusht. Bulkbewerkingen — een product verwijderen, een magazijn resetten — schrijven voorraad zonder een gebeurtenis te activeren, wat een reden is om ook de geplande voorraadstap te behouden.',
'Shopify_G_Nothing_Install' => 'Verder niets te installeren',
'Shopify_G_No_Worker_Note' => 'Geen van beide helften heeft een wachtrij-worker of cronregel nodig. Een binnenkomende webhook wordt afgehandeld in het verzoek dat Shopify doet; een uitgaande voorraadpush draait in hetzelfde proces dat de verkoop afhandelde, {after} het antwoord is teruggestuurd — dus de kassa wacht nooit op Shopify, en een winkel die niet meer reageert, wordt na tien seconden opgegeven en overgelaten aan de volgende geplande voorraadpush.',
'Shopify_G_After' => 'nadat',
'Shopify_G_Artisan_Note' => 'Eén uitzondering: een voorraadwijziging door een artisan-opdracht heeft geen antwoord om op te wachten, dus die wordt in plaats daarvan in de wachtrij {queue} geplaatst. Als u wilt dat ook die snel worden verzonden, verwerkt u die wachtrij:',
'Shopify_G_On_Schedule' => 'Volgens schema',
'Shopify_G_On_Lower' => 'aan',
'Shopify_G_Off_Lower' => 'uit',
'Shopify_G_Scheduled_Lead' => 'Alles wordt regelmatig opnieuw gecontroleerd, in beide richtingen. Trager dan realtime, maar het is wat voorraad pusht bij winkels zonder directe push, wat een gemiste webhook opvangt, en de enige manier om een hele catalogus te verplaatsen.',
'Shopify_G_Cron_Entry' => 'De cronregel',
'Shopify_G_Cron_Entry_Desc' => 'Zonder deze regel draait er niets gepland. Eén regel, alleen voor deze module — voeg deze toe naast wat u verder heeft gepland:',
'Shopify_G_Cron_Note' => 'Elke vijf minuten is de fijnste resolutie die een plan kan gebruiken, omdat vijf minuten het kortste stapinterval is. Een grovere regel wordt simpelweg de ondergrens — met {example} draait een stap die op 5 minuten staat elke 15. Gebruik op Windows Taakplanner: programma {program}, argumenten {args}, gestart in {dir}.',
'Shopify_G_Switch_On_Plan' => 'Schakel het in en kies het plan',
'Shopify_G_Plan_Desc' => '{where} De schakelaar bepaalt of cron überhaupt mag handelen; het plan bepaalt wat het doet. Een {step} is één entiteit in één richting met een eigen interval — {first}, {second}. Het standaardinterval wordt gebruikt door elke stap die het eigen vak leeg laat.',
'Shopify_G_Step_Lower' => 'stap',
'Shopify_G_Plan_Note' => 'Laat het plan leeg en de winkel haalt bestellingen op en pusht voorraad volgens het standaardinterval, wat de meeste winkels willen. Bestellingen worden alleen opgehaald: Shopify is waar een klant er een plaatst.',
'Shopify_G_Schedule_On' => 'schema aan',
'Shopify_G_Schedule_Off' => 'schema uit — alleen handmatig',
'Shopify_G_When_Step_Runs' => 'Wanneer een stap daadwerkelijk draait',
'Shopify_G_When_Note' => 'Een stap is aan de beurt wanneer diezelfde stap langer geleden is {started} dan het interval, gelezen uit de rungeschiedenis. Een handmatig gestarte synchronisatie stelt dus de volgende automatische uit, en een stap die blijft mislukken wordt opnieuw geprobeerd volgens het interval in plaats van bij elke tick. Het Overzicht van de winkel toont voor elke stap de laatste run, het volgende moment en de reden waarom deze geblokkeerd is, als dat zo is. Voer de eerste cataloguspush handmatig uit — eerst met {dryRun} — voordat u deze inplant.',
'Shopify_G_Started_Lower' => 'gestart',
'Shopify_G_Where_Setting' => 'Waar elke instelling staat',
'Shopify_G_Where_Setting_Note' => 'Al deze instellingen staan bij een bestaande winkel: {path}, dan het potlood (of {edit} op de eigen pagina van de winkel).',
'Shopify_G_Product_Images' => 'Productafbeeldingen',
'Shopify_G_Img_1' => 'Afbeeldingen gaan mee met het product bij een {push} — eerst de hoofdafbeelding, dan de galerij, dan één per variant met een eigen afbeelding, tot vijftig.',
'Shopify_G_Products_Push' => 'productpush',
'Shopify_G_Img_2' => 'De afbeelding van een variant wordt met het product geüpload en daarna {assigned}, zo modelleert Shopify het: een variant verwijst naar een van de afbeeldingen van het product. Een variant die de hoofdafbeelding hergebruikt, uploadt deze niet twee keer.',
'Shopify_G_Assigned' => 'aan die variant toegewezen',
'Shopify_G_Img_3' => 'Een afbeelding die als bestand is opgeslagen, wordt naar Shopify {uploaded}, niet gelinkt, dus het werkt zelfs als deze installatie niet via internet bereikbaar is. Een afbeelding die als geplakte link is toegevoegd, wordt als die URL aan Shopify doorgegeven en moet openbaar bereikbaar zijn.',
'Shopify_G_Uploaded' => 'geüpload',
'Shopify_G_Img_4' => 'Ze worden alleen opnieuw verzonden wanneer ze daadwerkelijk veranderen — een push die alleen een prijs wijzigt, laat de afbeeldingen van de winkel ongemoeid, omdat verzenden de hele set vervangt.',
'Shopify_G_Img_5' => 'Een afbeelding verwijderen in het ERP verwijdert deze {not} in Shopify. Verwijder deze daar ook, anders blijft de winkel hem tonen.',
'Shopify_G_Commands' => 'Handige opdrachten',
'Shopify_G_Command_Copied' => 'Opdracht gekopieerd',
'Shopify_G_Foot' => 'Elke synchronisatie schrijft naar {logs}, en het Overzicht van elke winkel toont wanneer elke stap voor het laatst draaide, wanneer deze weer aan de beurt is en wat deze blokkeert als dat zo is. Daar kijkt u eerst wanneer een synchronisatie niet deed wat u verwachtte.',
'Shopify_G_Covers' => 'Omvat',
'Shopify_G_Covers_Rt' => 'Bestellingen en wijzigingen in Shopify; voorraad die het ERP verlaat (een POS-verkoop, een retour, een correctie)',
'Shopify_G_Covers_Sch' => 'Alles, in beide richtingen — inclusief cataloguspushes en alles wat de snelle route miste',
'Shopify_G_Speed' => 'Snelheid',
'Shopify_G_Speed_Rt' => 'Seconden',
'Shopify_G_Speed_Sch' => 'Het interval van de stap (5 minuten tot 7 dagen)',
'Shopify_G_Needs' => 'Vereist',
'Shopify_G_Needs_Rt' => 'Een openbaar HTTPS-adres en het ondertekeningssecret voor inkomende webhooks. Uitgaande voorraad heeft helemaal niets nodig',
'Shopify_G_Needs_Sch' => 'Een cronregel die {cmd} uitvoert',
