'StoreAdm_PG_Intro_Msg' => 'PayPal, Paystack, Flutterwave, Razorpay, bKash en SSLCommerz worden alleen gebruikt bij het afrekenen in de WEBWINKEL.',
'StoreAdm_PG_Intro_Desc' => 'Stripe-sleutels worden globaal gedeeld (beheer en webwinkel gebruiken dezelfde Stripe-integratie). Elk tabblad schakelt de betreffende methode in of uit voor het afrekenen in de webwinkel; Offline betalingen bevat de methoden die buiten het systeem worden betaald.',
