'StoreAdm_PG_Paypal_Webhook_Hint' => 'Vangnet voor betalingen waarvan de browserdoorverwijzing nooit aankomt, plus terugbetalingen/chargebacks. Registreer een webhook op {site} die naar de onderstaande URL wijst (gebeurtenissen: {events}) en plak de Webhook ID hier.',
