'StoreAdm_PG_Gw_Disabled' => '{gw} is uitgeschakeld',
'StoreAdm_PG_Paypal_Disabled_Desc' => 'Schakel PayPal in en voer de Client ID en het Secret van uw REST-app in (van {site}) zodat klanten bij het afrekenen in de webwinkel met PayPal kunnen betalen.',
