'StoreAdm_PG_Paystack_Test_Live' => 'Test of live wordt bepaald door het sleutelpaar: {test}-sleutels werken in testmodus, {live}-sleutels belasten echte kaarten — er is geen aparte sandboxschakelaar.',
'StoreAdm_PG_Paystack_Webhook_Url' => 'Webhook-URL (optioneel vangnet — stel deze in onder Settings → API Keys & Webhooks op het Paystack-dashboard; verzoeken worden met HMAC geverifieerd met uw secret key):',
'StoreAdm_PG_Paystack_Disabled_Desc' => 'Schakel Paystack in en voer uw Public en Secret keys in (van {site} → Settings → API Keys) om kaarten, bankoverschrijvingen en mobiel geld te accepteren bij het afrekenen in de webwinkel.',
'StoreAdm_PG_Secret_Hash_Opt' => 'Secret Hash (webhooks, optioneel)',
'StoreAdm_PG_Flutterwave_Hash_Hint' => 'De Secret Hash die u instelt onder Settings → Webhooks op het Flutterwave-dashboard; inkomende webhooks worden geweigerd tenzij hun {header}-header overeenkomt.',
'StoreAdm_PG_Flutterwave_Info' => 'Gebruikt de Flutterwave v3 API met klassieke sleutels. Test of live wordt bepaald door het sleutelpaar ({keys} vs live-sleutels) — er is geen aparte sandboxschakelaar. De winkelvaluta moet zijn ingeschakeld op uw Flutterwave-account.',
